// Normalize and validate incoming lead data.
// Website URLs are user-controlled, so reject obvious local/private targets before HTTP fetching.
// NOTE: rewritten without the WHATWG URL class -- it is not available in this Code node's
// sandbox, which was silently causing normalizeWebsite() to throw and return '' for every URL.
const input = $input.first().json;
const body = input.body || input;

const clean = (v) => String(v ?? '').trim();
const name = clean(body.name);
const email = clean(body.email).toLowerCase();
const company = clean(body.company);
const message = clean(body.message);
const budget = clean(body.budget) || 'Not specified';

const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const domain = emailValid ? email.split('@').pop().toLowerCase() : '';

const freeEmailDomains = new Set([
  'gmail.com','googlemail.com','yahoo.com','yahoo.co.uk','outlook.com','hotmail.com',
  'live.com','icloud.com','me.com','aol.com','proton.me','protonmail.com','gmx.com','mail.com'
]);

function normalizeWebsite(raw) {
  raw = clean(raw);
  if (!raw) return '';
  if (!/^https?:\/\//i.test(raw)) raw = 'https://' + raw;

  // Manual parse: protocol://[user[:pass]@]host[:port][/path][?query][#hash]
  const m = raw.match(/^(https?):\/\/(?:([^\/?#@:]*)(?::([^\/?#@]*))?@)?(\[[0-9a-fA-F:]+\]|[^\/?#:]+)(?::(\d+))?([^?#]*)(\?[^#]*)?(#.*)?$/i);
  if (!m) return '';

  const [, protocol, username, password, hostRaw, port, pathRaw] = m;
  if (username || password) return '';

  let h = hostRaw.toLowerCase();
  const isBracketed = h.startsWith('[') && h.endsWith(']');
  if (isBracketed) h = h.slice(1, -1); // strip [] for IPv6 checks

  if (h === 'localhost' || h.endsWith('.local')) return '';
  if (/^(127\.|10\.|0\.|169\.254\.|192\.168\.)/.test(h)) return '';
  const mm = h.match(/^172\.(\d+)\./);
  if (mm && Number(mm[1]) >= 16 && Number(mm[1]) <= 31) return '';
  if (h === '::1' || h.startsWith('fc') || h.startsWith('fd') || h.startsWith('fe80:')) return '';

  const path = pathRaw && pathRaw.length ? pathRaw : '/';
  const portPart = port ? ':' + port : '';
  const hostPart = isBracketed ? `[${h}]` : h;
  return `${protocol.toLowerCase()}://${hostPart}${portPart}${path}`;
}

let website = normalizeWebsite(body.website);
if (!website && domain && !freeEmailDomains.has(domain)) {
  website = normalizeWebsite('https://' + domain);
}

return [{
  json: {
    name,
    email,
    company,
    message,
    budget,
    website,
    domain,
    is_valid_email: emailValid
  }
}];

// Convert fetched HTML to compact company context while preserving the original lead fields.
const lead = $('Normalize Lead Data').first().json;
const input = $input.first().json;
let html = input.data ?? input.body ?? '';
if (typeof html !== 'string') html = '';

const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 2500);

return [{
  json: {
    ...lead,
    website_context: text || 'No website content available.'
  }
}];

