const input = $input.first().json;

let parsed = {};
if (input && typeof input === 'object' && input.score !== undefined) {
  parsed = input;
} else {
  let aiText = input?.text ?? input?.output ?? input?.content ?? input?.response ?? input?.message?.content ?? '';
  if (typeof aiText === 'object' && aiText !== null) {
    parsed = aiText;
  } else {
    if (typeof aiText !== 'string') aiText = String(aiText ?? '');
    try {
      const cleaned = aiText.replace(/```json|```/gi, '').trim();
      const match = cleaned.match(/\{[\s\S]*\}/);
      parsed = JSON.parse(match ? match[0] : cleaned);
    } catch (e) {
      parsed = {};
    }
  }
}

let score = Number(parsed.score);
if (!Number.isFinite(score)) score = 1;
score = Math.max(1, Math.min(10, Math.round(score)));

const category = score >= 8 ? 'Hot' : score >= 5 ? 'Warm' : 'Cold';
const followupDays = category === 'Hot' ? 1 : category === 'Warm' ? 3 : null;

const lead = $('Normalize Lead Data').first().json;
const reasoning = String(parsed.reasoning || 'AI response could not be parsed reliably; defaulted conservatively.').slice(0, 500);
const suggestedReply = String(parsed.suggested_reply_opener || '').slice(0, 500);

return [{
  json: {
    name: lead.name,
    email: lead.email,
    company: lead.company,
    message: lead.message,
    budget: lead.budget,
    website: lead.website,
    score,
    category,
    reasoning,
    suggested_reply_opener: suggestedReply,
    timestamp: new Date().toISOString(),
    followed_up: false,
    followup_days: followupDays,
    followup_sent_at: ''
  }
}];

// Keep only Hot/Warm leads that are past their follow-up window and haven't been followed up yet.
const items = $input.all();
const now = Date.now();

const due = items.filter((item) => {
  const j = item.json;
  const category = String(j.category || '');
  if (category !== 'Hot' && category !== 'Warm') return false;

  const alreadyFollowedUp = j.followed_up === true || j.followed_up === 'true' || j.followed_up === 'TRUE';
  if (alreadyFollowedUp) return false;

  const days = Number(j.followup_days);
  if (!Number.isFinite(days)) return false;

  const ts = Date.parse(j.timestamp);
  if (!Number.isFinite(ts)) return false;

  const dueAt = ts + days * 24 * 60 * 60 * 1000;
  return now >= dueAt;
});

// Always return exactly one output: either the due leads, or an explicit
// 'nothing due' marker item so the run has a clean, visible end-state
// instead of just stopping with zero items partway through the canvas.
if (due.length === 0) {
  return [{ json: { _no_leads_due: true, checked_count: items.length } }];
}

return due.map((item) => ({ json: item.json }));

const lead = $('Filter Due Leads').item.json;
return {
  json: {
    ...lead,
    followed_up: true,
    followup_sent_at: new Date().toISOString()
  }
};

const lead = $('Filter Due Leads').item.json;
return {
  json: {
    ...lead,
    followed_up: true,
    followup_sent_at: 'skipped-lead-replied'
  }
};
